 701→+func (d *githubHTTPDispatcher) DispatchRepositoryEvent(ctx context.Context, payload slacktriage.DispatchPayload) error {
 702→+	body, err := json.Marshal(struct {
 703→+		EventType     string                      `json:"event_type"`
 704→+		ClientPayload slacktriage.DispatchPayload `json:"client_payload"`
 705→+	}{
 706→+		EventType:     d.eventType,
 707→+		ClientPayload: payload,
 708→+	})
 709→+	if err != nil {
 710→+		return fmt.Errorf("marshal github dispatch payload: %w", err)
 711→+	}
 712→+
 713→+	endpoint := fmt.Sprintf("%s/repos/%s/dispatches", d.baseURL, d.repository)
 714→+	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
 715→+	if err != nil {
 716→+		return fmt.Errorf("build github dispatch request: %w", err)
 717→+	}
 718→+	req.Header.Set("Authorization", "Bearer "+d.token)
 719→+	req.Header.Set("Accept", "application/vnd.github+json")
 720→+	req.Header.Set("Content-Type", "application/json")
 721→+
 722→+	//nolint:gosec // GitHub API base URL and repository are operator-configured.
 723→+	resp, err := d.client.Do(req)
 724→+	if err != nil {
 725→+		return fmt.Errorf("call github dispatch endpoint: %w", err)
 726→+	}
 727→+	defer resp.Body.Close()
 728→+
 729→+	if resp.StatusCode != http.StatusNoContent {
 730→+		responseBody, readErr := io.ReadAll(io.LimitReader(resp.Body, 4096))
 731→+		if readErr != nil {
 732→+			return fmt.Errorf("github dispatch failed: %s (read response): %w", resp.Status, readErr)
 733→+		}
 734→+		if len(responseBody) > 0 {
 735→+			return fmt.Errorf("github dispatch failed: %s: %s", resp.Status, strings.TrimSpace(string(responseBody)))
 736→+		}
 737→+		return fmt.Errorf("github dispatch failed: %s", resp.Status)
 738→+	}
 739→+
 740→+	return nil
 741→+}
